using System;
using System.ComponentModel;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.Windows.Forms;
namespace ZenForms.Core
{
    public sealed class ZenFormulaErrorEventArgs : EventArgs { public string Message { get; private set; } public ZenFormulaErrorEventArgs(string message) { Message = message; } }
    [Category("ZenForms Modern Components")]
    [Description("Math ploter.")]
    public class ZenFormulaPlotter : UserControl
    {
        private readonly TextBox input; private readonly Label status; private readonly PlotSurface surface; private Func<double, double> function; private string formula = "sin(x)"; private double centerX, centerY, scale = 40; private Color curveColor = ZenTheme.Accent;
        [Category("ZenForms Formula"), DefaultValue("sin(x)")] public string Formula { get { return formula; } set { formula = value ?? ""; input.Text = formula; Plot(); } }
        [Category("ZenForms Appearance")] public Color CurveColor { get { return curveColor; } set { curveColor = value; surface.Invalidate(); } }
        public event EventHandler<ZenFormulaErrorEventArgs> FormulaError;
        public ZenFormulaPlotter() { Size = new Size(640, 420); BackColor = ZenTheme.Background; Panel top = new Panel { Dock = DockStyle.Top, Height = 42, BackColor = ZenTheme.Surface, Padding = new Padding(8, 6, 8, 5) }; Label fx = new Label { Dock = DockStyle.Left, Width = 30, Text = "f(x)=", ForeColor = ZenTheme.Accent, Font = new Font("Segoe UI Semibold", 9f), TextAlign = ContentAlignment.MiddleCenter }; input = new TextBox { Dock = DockStyle.Fill, Text = formula, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground, BorderStyle = BorderStyle.FixedSingle, Font = new Font("Consolas", 10f) }; Button plot = new Button { Dock = DockStyle.Right, Width = 72, Text = "Plotte", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.Primary, ForeColor = Color.White }; top.Controls.Add(input); top.Controls.Add(plot); top.Controls.Add(fx); status = new Label { Dock = DockStyle.Bottom, Height = 22, BackColor = ZenTheme.Surface, ForeColor = ZenTheme.Muted, Font = new Font("Segoe UI", 8f), TextAlign = ContentAlignment.MiddleLeft, Padding = new Padding(8, 0, 0, 0) }; surface = new PlotSurface(this) { Dock = DockStyle.Fill, BackColor = Color.FromArgb(12, 16, 28) }; Controls.Add(surface); Controls.Add(status); Controls.Add(top); plot.Click += (s, e) => Plot(); input.KeyDown += (s, e) => { if (e.KeyCode == Keys.Enter) { Plot(); e.SuppressKeyPress = true; } }; Plot(); }
        public void Plot() { formula = input.Text.Trim(); try { function = ExpressionParser.Compile(formula); status.Text = "f(x) = " + formula + "     •     Scroll: zoom   |   Drag: mover"; surface.Invalidate(); } catch (Exception ex) { function = null; status.Text = "Invalid Expression: " + ex.Message; EventHandler<ZenFormulaErrorEventArgs> h = FormulaError; if (h != null) h(this, new ZenFormulaErrorEventArgs(ex.Message)); surface.Invalidate(); } }
        private sealed class PlotSurface : Control
        {
            private readonly ZenFormulaPlotter owner; private Point last; private bool drag; public PlotSurface(ZenFormulaPlotter o) { owner = o; SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true); }
            protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { drag = true; last = e.Location; Capture = true; } }
            protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); drag = false; Capture = false; }
            protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); if (!drag) return; owner.centerX -= (e.X - last.X) / owner.scale; owner.centerY += (e.Y - last.Y) / owner.scale; last = e.Location; Invalidate(); }
            protected override void OnMouseWheel(MouseEventArgs e) { base.OnMouseWheel(e); double old = owner.scale; owner.scale = Math.Max(8, Math.Min(240, old * (e.Delta > 0 ? 1.15 : .87))); double x0 = (e.X - Width / 2.0) / old + owner.centerX, y0 = (Height / 2.0 - e.Y) / old + owner.centerY; owner.centerX = x0 - (e.X - Width / 2.0) / owner.scale; owner.centerY = y0 - (Height / 2.0 - e.Y) / owner.scale; Invalidate(); }
            protected override void OnPaint(PaintEventArgs e) { base.OnPaint(e); Graphics g = e.Graphics; g.SmoothingMode = SmoothingMode.AntiAlias; g.Clear(BackColor); float cx = Width / 2f, cy = Height / 2f; using (Pen grid = new Pen(Color.FromArgb(28, 140, 155, 180))) for (float x = cx + (float)((-owner.centerX * owner.scale) % owner.scale); x < Width; x += (float)owner.scale) g.DrawLine(grid, x, 0, x, Height); using (Pen grid = new Pen(Color.FromArgb(28, 140, 155, 180))) for (float y = cy + (float)((owner.centerY * owner.scale) % owner.scale); y < Height; y += (float)owner.scale) g.DrawLine(grid, 0, y, Width, y); using (Pen axes = new Pen(Color.FromArgb(115, ZenTheme.Muted), 1.2f)) { float ax = cx - (float)(owner.centerX * owner.scale), ay = cy + (float)(owner.centerY * owner.scale); if (ax >= 0 && ax <= Width) g.DrawLine(axes, ax, 0, ax, Height); if (ay >= 0 && ay <= Height) g.DrawLine(axes, 0, ay, Width, ay); } if (owner.function == null) { using (Font hintFont = new Font("Segoe UI", 10f)) TextRenderer.DrawText(g, "Enter with a valid expression. Example: sin(x) + x^2 / 5", hintFont, ClientRectangle, ZenTheme.Muted, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.WordBreak); return; } using (Pen curve = new Pen(owner.curveColor, 2.5f)) { curve.LineJoin = LineJoin.Round; PointF prev = PointF.Empty; bool have = false; for (int px = 0; px < Width; px++) { double x = (px - cx) / owner.scale + owner.centerX; try { double y = owner.function(x); double py = cy - (y - owner.centerY) * owner.scale; if (Double.IsNaN(py) || Double.IsInfinity(py) || Math.Abs(py) > Height * 20) { have = false; continue; } PointF p = new PointF(px, (float)py); if (have && Math.Abs(p.Y - prev.Y) < Height * 1.5f) g.DrawLine(curve, prev, p); prev = p; have = true; } catch { have = false; } } } }
        }
        private sealed class ExpressionParser
        {
            private readonly string text; private int pos; private ExpressionParser(string s) { text = s; }
            public static Func<double, double> Compile(string s) { if (String.IsNullOrWhiteSpace(s)) throw new FormatException("empty expression"); ExpressionParser p = new ExpressionParser(s); Func<double, double> f = p.ParseExpression(); p.Skip(); if (p.pos < p.text.Length) throw new FormatException("unexpected symbol: " + p.text[p.pos]); return f; }
            private Func<double, double> ParseExpression() { Func<double, double> left = ParseTerm(); while (true) { Skip(); if (Take('+')) { Func<double, double> a = left, b = ParseTerm(); left = x => a(x) + b(x); } else if (Take('-')) { Func<double, double> a = left, b = ParseTerm(); left = x => a(x) - b(x); } else return left; } }
            private Func<double, double> ParseTerm() { Func<double, double> left = ParsePower(); while (true) { Skip(); if (Take('*')) { Func<double, double> a = left, b = ParsePower(); left = x => a(x) * b(x); } else if (Take('/')) { Func<double, double> a = left, b = ParsePower(); left = x => a(x) / b(x); } else return left; } }
            private Func<double, double> ParsePower() { Func<double, double> a = ParseUnary(); Skip(); if (Take('^')) { Func<double, double> b = ParsePower(); return x => Math.Pow(a(x), b(x)); } return a; }
            private Func<double, double> ParseUnary() { Skip(); if (Take('+')) return ParseUnary(); if (Take('-')) { Func<double, double> a = ParseUnary(); return x => -a(x); } return ParsePrimary(); }
            private Func<double, double> ParsePrimary() { Skip(); if (Take('(')) { Func<double, double> f = ParseExpression(); Skip(); if (!Take(')')) throw new FormatException("close the parentheses"); return f; } if (pos >= text.Length) throw new FormatException("Incomplete expression"); char c = text[pos]; if (Char.IsDigit(c) || c == '.') return ParseNumber(); if (Char.IsLetter(c)) { string name = ParseName().ToLowerInvariant(); if (name == "x") return x => x; if (name == "pi") return x => Math.PI; if (name == "e") return x => Math.E; Skip(); if (!Take('(')) throw new FormatException("the use of '(' after the " + name + " was expected"); Func<double, double> a = ParseExpression(); Skip(); if (!Take(')')) throw new FormatException("forgot to close the function " + name); switch (name) { case "sin": return x => Math.Sin(a(x)); case "cos": return x => Math.Cos(a(x)); case "tan": return x => Math.Tan(a(x)); case "sqrt": return x => Math.Sqrt(a(x)); case "abs": return x => Math.Abs(a(x)); case "log": return x => Math.Log10(a(x)); case "ln": return x => Math.Log(a(x)); case "exp": return x => Math.Exp(a(x)); case "floor": return x => Math.Floor(a(x)); case "ceil": return x => Math.Ceiling(a(x)); default: throw new FormatException("function not supported: " + name); } } throw new FormatException("invalid token: " + c); }
            private Func<double, double> ParseNumber() { int start = pos; while (pos < text.Length && (Char.IsDigit(text[pos]) || text[pos] == '.')) pos++; double n; if (!Double.TryParse(text.Substring(start, pos - start), NumberStyles.Float, CultureInfo.InvariantCulture, out n)) throw new FormatException("invalid number"); return x => n; }
            private string ParseName() { int start = pos; while (pos < text.Length && Char.IsLetter(text[pos])) pos++; return text.Substring(start, pos - start); }
            private void Skip() { while (pos < text.Length && Char.IsWhiteSpace(text[pos])) pos++; }
            private bool Take(char c) { if (pos < text.Length && text[pos] == c) { pos++; return true; } return false; }
        }
    }
}

